{
  "name": "电动旋转夹爪",
  "name_en": "Electric Rotary Gripper",
  "manufacturer": "DH Robotics",
  "description": "一种用于机器人末端执行的电动夹爪，具备夹持开合与旋转两个自由度，可设置夹持位置、速度、夹持力以及旋转角度。该设备常用于实验室自动化中的样品抓取、上下料、工件搬运和定位操作。",
  "description_en": "An electric robotic gripper with both gripping and rotational motion, allowing control of grip position, speed, gripping force, and rotation angle. It is commonly used in laboratory automation for sample handling, loading and unloading, part transfer, and positioning tasks.",
  "tag_hints": [
    "electric rotary gripper",
    "robotic end effector",
    "parallel gripping",
    "sample handling",
    "lab automation",
    "Modbus serial control",
    "force and position control"
  ],
  "actions": [
    {
      "action_name": "auto-cal_crc",
      "description": "计算通信数据帧的 CRC 校验值",
      "description_en": "Calculate the CRC checksum for a communication frame."
    },
    {
      "action_name": "auto-read_uart",
      "description": "读取夹爪串口返回数据",
      "description_en": "Read serial data returned by the gripper."
    },
    {
      "action_name": "auto-write_uart",
      "description": "通过串口/Modbus向夹爪发送命令并可读取响应",
      "description_en": "Send a command to the gripper over serial/Modbus and optionally read the response."
    },
    {
      "action_name": "auto-init_state",
      "description": "初始化夹爪",
      "description_en": "Initialize the gripper."
    },
    {
      "action_name": "auto-set_force",
      "description": "设置夹持力",
      "description_en": "Set the gripping force."
    },
    {
      "action_name": "auto-set_pos",
      "description": "设置夹爪开合位置",
      "description_en": "Set the gripper opening position."
    },
    {
      "action_name": "auto-set_vel",
      "description": "设置夹爪开合速度",
      "description_en": "Set the gripper opening/closing speed."
    },
    {
      "action_name": "auto-set_abs_rot",
      "description": "设置绝对旋转角度",
      "description_en": "Set the absolute rotation angle."
    },
    {
      "action_name": "auto-set_rot_vel",
      "description": "设置旋转速度",
      "description_en": "Set the rotation speed."
    },
    {
      "action_name": "auto-set_rot_force",
      "description": "设置旋转力",
      "description_en": "Set the rotation force."
    },
    {
      "action_name": "auto-set_rel_rot",
      "description": "设置相对旋转角度",
      "description_en": "Set the relative rotation angle."
    },
    {
      "action_name": "auto-init_feedback",
      "description": "初始化夹持反馈",
      "description_en": "Initialize gripping feedback."
    },
    {
      "action_name": "auto-read_state",
      "description": "读取夹爪状态",
      "description_en": "Read the gripper state."
    },
    {
      "action_name": "auto-read_pos",
      "description": "读取夹爪位置",
      "description_en": "Read the gripper position."
    },
    {
      "action_name": "auto-read_cur",
      "description": "读取夹爪电流",
      "description_en": "Read the gripper current."
    },
    {
      "action_name": "auto-read_err",
      "description": "读取错误状态",
      "description_en": "Read the error status."
    },
    {
      "action_name": "auto-read_rot",
      "description": "读取旋转角度",
      "description_en": "Read the rotation angle."
    },
    {
      "action_name": "auto-init_rot_feedback",
      "description": "初始化旋转反馈",
      "description_en": "Initialize rotation feedback."
    },
    {
      "action_name": "auto-read_rot_state",
      "description": "读取旋转状态",
      "description_en": "Read the rotation state."
    },
    {
      "action_name": "auto-init_dir",
      "description": "设置初始化方向（0 为打开，1 为闭合）",
      "description_en": "Set the initialization direction (0 for open, 1 for close)."
    }
  ]
}

